import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Разделитель изображений разрезает одну картинку на несколько меньших частей. Части могут образовать сетку для профиля в соцсети, полосы для карусели или срезы для печати большого изображения на многих страницах. Исходное изображение остаётся нетронутым: разделитель просто даёт вам его части.</p>\n<p><a href=\"/ru/razdelit-izobrazhenie/\">Разделитель изображений</a> делит фото на плитки сетки N на M, горизонтальные строки или вертикальные полосы и скачивает части по отдельности или одним ZIP-архивом. Он работает полностью в вашем браузере, поэтому фото никогда не покидают устройство.</p>\n<p>Это руководство объясняет три режима разреза, предустановки, варианты экспорта и задачи, для которых лучше всего подходит каждый режим. Планируете ли вы сетку Instagram, разрезаете панораму или режете длинный скриншот для печати, разрез — это одна и та же простая идея.</p>\n<h2 id=\"what-is-an-image-splitter\">Что такое разделитель изображений</h2>\n<p>Разделитель изображений делит одно изображение на набор меньших изображений по прямым линиям разреза. Разрез сетки 3 на 3 превращает одно квадратное фото в девять квадратных плиток. Горизонтальный разрез превращает высокое изображение в сложенные строки, а вертикальный — широкое изображение в соседние столбцы.</p>\n<p>Каждая плитка — это настоящий файл изображения, а не предпросмотр обрезки. Вы можете скачать плитки по одной или все сразу в ZIP-архиве, а затем использовать их везде, где нужны отдельные изображения: в постах соцсетей, на страницах печати, в плитках игры или макетах дизайна.</p>\n<p>Разрез неразрушающий. Исходный файл никогда не меняется, и вы можете разделить то же изображение снова с другими настройками столько раз, сколько хотите. Сетка 3 на 3 сегодня и сетка 2 на 4 завтра — обе из одного нетронутого источника.</p>\n<p>Разделение отличается от обрезки. Обрезка выбрасывает часть изображения, чтобы сохранить один кусок, а разделение сохраняет каждую часть и даёт вам их все. Плитки вместе содержат всё исходное изображение, просто в отдельных файлах.</p>\n<h2 id=\"grid-mode\">Режим сетки: плитки N на M</h2>\n<p>Режим сетки — основной. Вы задаёте число строк и столбцов, и инструмент делит изображение на столько равных плиток. Сетка 3 на 3 даёт девять плиток, сетка 2 на 4 — восемь, а максимальная сетка — 10 на 10, что даёт сто плиток из одного изображения.</p>\n<p>Сетка — это режим для сеток профиля Instagram, где девять квадратных плиток образуют одно большое изображение на странице профиля. Это также режим для пазлов, мозаик и любого макета, где плитки сидят рядом, чтобы восстановить оригинал.</p>\n<p>Каждая плитка разрезается в полном исходном размере в пикселях, поэтому фото 3000 пикселей, разрезанное 3 на 3, даёт девять плиток по 1000 пикселей. Ничего не уменьшается и не пересэмплируется, а значит, плитки остаются достаточно резкими для печати или публикации в полном качестве.</p>\n<p>На предпросмотре появляются пронумерованные линии разреза, поэтому вы видите ровно, где начинается и заканчивается каждая плитка, прежде чем скачать. Если линия разреза проходит через лицо или важную деталь, измените сетку или переместите изображение, а не принимайте плохой разрез.</p>\n<h2 id=\"horizontal-strips\">Горизонтальные полосы</h2>\n<p>Горизонтальные полосы разрезают изображение на сложенные строки. Высокое изображение, разрезанное на четыре горизонтальные полосы, даёт четыре широких, коротких изображения, которые читаются сверху вниз, как страницы длинного документа.</p>\n<p>Этот режим подходит длинным скриншотам, которые нужно напечатать. Скриншот всей страницы слишком высок для одного листа бумаги, но четыре горизонтальные полосы чисто печатаются на четырёх страницах. Та же идея работает для высоких инфографик, которые нужно показать как отдельные слайды.</p>\n<p>Горизонтальные полосы также подходят каруселям в соцсетях, где каждый слайд продолжает изображение вниз. Зритель листает полосы, и картинка раскрывается по порядку, что создаёт простой эффект повествования.</p>\n<p>Выбирайте число полос под место назначения. Четыре полосы для четырёх печатных страниц, три — для карусели из трёх слайдов, две — для простого разреза на верх и низ. Полосы равной высоты, поэтому содержимое делится равномерно.</p>\n<h2 id=\"vertical-strips\">Вертикальные полосы</h2>\n<p>Вертикальные полосы разрезают изображение на соседние столбцы. Широкая панорама, разрезанная на три вертикальные полосы, даёт три высоких изображения, которые читаются слева направо, как панели триптиха.</p>\n<p>Этот режим подходит широким панорамам и баннерам, которые слишком широки для одного поста или одной страницы. Панораму, разрезанную на вертикальные полосы, можно опубликовать как карусель, где каждый свайп открывает следующую часть сцены, — это подходит фото путешествий и пейзажам.</p>\n<p>Вертикальные полосы также подходят баннерам и шапкам сайтов, которые нужно восстановить по столбцам. Дизайнер может разместить каждую полосу в своём столбце и собрать панораму заново в макете, куда одно широкое изображение не поместилось бы.</p>\n<p>Как и горизонтальные полосы, вертикальные имеют равную ширину, поэтому содержимое делится равномерно. У панорамы с объектом в центре может понадобиться нечётное число полос, чтобы объект попал в среднюю полосу, а не на линию разреза.</p>\n<h2 id=\"split-presets\">Предустановки разреза</h2>\n<p>Предустановки — это настройки разреза в один клик для распространённых задач. Сетка Instagram 3 на 3 — самая известная предустановка, но инструмент включает и другие для распространённых размеров сетки и числа полос, поэтому ручные настройки строк и столбцов можно пропустить.</p>\n<p>Предустановка — это отправная точка, а не правило. Нажмите предустановку 3 на 3 для сетки Instagram, затем поправьте строки или столбцы, если вашему изображению или плану нужна другая форма. Предустановка заполняет числа, а вы сохраняете свободу их менять.</p>\n<p>Предустановки помогают, когда вы разделяете изображения часто. Менеджер соцсетей, который каждую неделю строит сетку, может нажимать ту же предустановку каждый раз и получать плитки одинакового размера, что сохраняет сетку профиля последовательной от одного пазла к другому.</p>\n<p>Если ни одна предустановка не подходит вашей задаче, задайте строки и столбцы вручную. Сетка 4 на 5 для постера, полоса 1 на 6 для баннера или сетка 5 на 5 для мозаики — все это допустимые разрезы, а ручные настройки покрывают каждую комбинацию до 10 на 10.</p>\n<h2 id=\"full-resolution-tiles\">Плитки в полном разрешении</h2>\n<p>Плитки разрезаются в полном исходном размере в пикселях, а значит, разрез никогда не снижает качество. Фото 3000 на 3000 пикселей, разрезанное на девять плиток, даёт девять изображений 1000 на 1000 пикселей, каждое такое же резкое, как соответствующая часть оригинала.</p>\n<p>Это важно для печати и больших дисплеев. Плитка, уменьшенная в размере, выглядела бы мягкой при печати или просмотре в полном размере, а плитка в полном разрешении сохраняет те же детали, что и источник. Разделитель — это инструмент разрезания, а не изменения размера.</p>\n<p>Компромисс — размер файла. Девять плиток в полном разрешении вместе примерно равны по общему размеру исходному изображению, а разрез 10 на 10 даёт сто файлов для управления. Скачайте ZIP-архив, чтобы держать их вместе, а не сохранять каждую плитку вручную.</p>\n<p>Начинайте с исходника самого высокого разрешения, какой у вас есть. Фото 600 пикселей, разрезанное 3 на 3, даёт девять плиток по 200 пикселей, которые хорошо выглядят как миниатюры, но плохо — как посты. Большой источник даёт большие плитки, а большие плитки переживают любое использование.</p>\n<h2 id=\"numbered-tiles-and-zip-download\">Пронумерованные плитки и скачивание ZIP</h2>\n<p>Каждая плитка пронумерована, чтобы вы знали, где ей место. Нумерация следует порядку чтения: слева направо, сверху вниз, начиная с верхнего левого угла. Плитка один — верхний левый кусок, а последняя плитка — нижний правый кусок.</p>\n<p>Нумерация важнее всего для сеток Instagram, где плитки нужно публиковать в обратном порядке, чтобы они встали на правильные места. Номера сообщают позицию каждой плитки в сетке, поэтому порядок публикации никогда не угадывается.</p>\n<p>ZIP-архив содержит все плитки в одном файле, названные по порядку. Скачивание ZIP быстрее, чем сохранение каждой плитки по отдельности, и оно держит набор вместе на вашем устройстве. Распакуйте его — и пронумерованные файлы готовы к использованию.</p>\n<p>Можно также скачивать плитки по отдельности, если нужны только одна-две из них. Одна плитка для фото профиля или одна полоса для баннера не требует весь набор, а отдельное скачивание избавляет от распаковки.</p>\n<h2 id=\"input-formats\">Входные форматы</h2>\n<p>Разделитель принимает файлы JPG, PNG, WebP, HEIC, GIF, BMP и SVG до 20 МБ. Фото с телефонов, скриншоты и графика из дизайнерских инструментов работают без преобразования. HEIC-фото с iPhone загружается и разделяется, как любой другой файл.</p>\n<p>Формат плиток следует вашему выбору, а не входному формату. Источник JPG может дать плитки PNG, а источник PNG — плитки JPG. Выбирайте формат под место назначения: JPG для фото и маленьких файлов, PNG для прозрачности и резкой графики.</p>\n<p>Обратите внимание, что ползунок «Качество плиток» появляется только для плиток JPG. Плитки PNG без потерь, поэтому настраивать качество там нечего. Если нужны самые маленькие файлы, выберите JPG и задайте качество; если нужны точные пиксели, выберите PNG.</p>\n<p>Анимированные GIF не разделяются как анимации. Загрузка анимированного GIF даёт плитки одного кадра, а не набор анимированных плиток. Разделяйте неподвижное изображение для сеток и полос, а анимации оставляйте целыми.</p>\n<h2 id=\"transparency-and-sprite-sheets\">Прозрачность и спрайт-листы</h2>\n<p>Разделение прозрачного PNG сохраняет прозрачность в каждой плитке. Спрайт-лист с прозрачными ячейками разделяется на прозрачные плитки — именно это нужно разработчикам игр, когда они разрезают лист иконок или набор плиток на отдельные спрайты.</p>\n<p>Для прозрачной работы выберите PNG как формат плиток. У JPG нет прозрачности, поэтому прозрачная плитка, экспортированная как JPG, получает сплошной фон, обычно белый или чёрный. Прозрачность переживает только формат, который её поддерживает.</p>\n<p>Спрайт-листам нужны точные разрезы. Лист иконок 32 на 32 пикселя, разрезанный на сетку, даёт плитки ровно по 32 пикселя каждая, если размеры листа делятся нацело. Проверьте размеры плиток после разреза, прежде чем использовать их в игровом движке.</p>\n<p>Когда лист не делится нацело, крайние плитки могут немного отличаться по размеру. Это нормально для разреза сетки и означает, что у листа есть поле или зазор, который сетка не учла. Сначала обрежьте источник до точного кратного размера, чтобы получить пиксельно точные плитки.</p>\n<h2 id=\"splitting-for-print\">Разделение для печати</h2>\n<p>Большое изображение, напечатанное на нескольких страницах, — классическое применение разделителя для печати. Постер, разрезанный на сетку плиток, печатается на многих листах бумаги, которые вы обрезаете и соединяете в большой постер. Номера плиток сообщают порядок.</p>\n<p>Горизонтальные полосы подходят длинным документам и баннерам, которые нужно напечатать на нескольких страницах. Высокая инфографика, разрезанная на четыре полосы, печатается на четырёх страницах, каждая — чистый раздел оригинала. Полосы равной высоты, поэтому страницы совпадают.</p>\n<p>Проверьте размеры плиток по размеру бумаги перед печатью. Плитка шире печатной области обрезается принтером, а плитка намного меньше тратит бумагу. Задайте сетку так, чтобы каждая плитка соответствовала листу.</p>\n<p>Печатайте в полном разрешении и не позволяйте принтеру масштабировать плитки. Масштабированная плитка теряет резкость, которую сохранил разрез в полном разрешении. Установите принтер на фактический размер — и плитки соединятся чисто.</p>\n<h2 id=\"splitting-screenshots\">Разделение скриншотов</h2>\n<p>Длинные скриншоты — это самое распространённое, что люди разделяют. Скриншот всей страницы сайта или чата слишком высок, чтобы читать его удобно, и слишком высок для печати, но горизонтальные полосы превращают его в читаемые разделы.</p>\n<p>Вставьте скриншот прямо из буфера обмена клавишами Ctrl и V. Разделитель принимает вставленные изображения, поэтому скриншот никогда не нужно сначала сохранять как файл. Вставьте, выберите число полос и скачайте разделы.</p>\n<p>Выбирайте число полос под содержимое. Скриншот с четырьмя естественными разделами разделяется на четыре полосы, а очень длинной странице может понадобиться шесть или восемь. Больше полос означает более короткие и читаемые разделы, но и больше файлов для управления.</p>\n<p>Следите за линиями разреза, проходящими через текст. Граница полосы, проходящая через строку текста, делает обе полосы трудными для чтения. Настраивайте число полос, пока границы не попадут в пробелы между абзацами или разделами.</p>\n<h2 id=\"common-mistakes\">Частые ошибки</h2>\n<p>Самая частая ошибка — разделить изображение низкого разрешения на слишком много плиток. Фото 600 пикселей, разрезанное 3 на 3, даёт девять плиток по 200 пикселей, которые плохо выглядят как посты. Начинайте с большого источника или используйте меньше плиток.</p>\n<p>Другая ошибка — линия разреза через лицо или ключевую деталь. Предпросмотр показывает линии разреза перед скачиванием, поэтому проверьте их и поправьте сетку или положение изображения. Лицо, разрезанное на две плитки, выглядит как ошибка, а не как дизайн.</p>\n<p>Третья ошибка — неверный формат плиток. Прозрачные плитки, экспортированные как JPG, теряют прозрачность и получают сплошной фон. Выбирайте PNG, когда важна прозрачность, и JPG, когда важен размер файла.</p>\n<p>Наконец, многие забывают порядок публикации для сеток. Instagram показывает сначала самый свежий пост, поэтому плитки сетки нужно публиковать в обратном порядке, чтобы они встали правильно. Номера плиток дают позицию в сетке; публикуйте от последней плитки к первой.</p>\n<p>Разделитель пригодится и для печати фото на домашнем принтере. Большое семейное фото, разрезанное на четыре части, печатается на обычных листах А4, а затем собирается в постер для стены без заказа в типографии.</p>\n<p>Для презентаций разрезанные полосы работают как отдельные слайды. Длинная инфографика, разрезанная на четыре полосы, превращается в четыре слайда, каждый из которых читается с экрана без уменьшения шрифта.</p>\n<p>Если вы готовите пазл для соцсетей, сначала сделайте пробный разрез и соберите плитки в коллаж на экране. Так вы увидите итоговую картинку до публикации и заметите неудачный разрез, пока его ещё легко исправить.</p>\n<p>Храните исходное изображение в отдельной папке вместе с ZIP-архивом плиток. Через месяц вы можете захотеть другую сетку, и исходник позволит разрезать заново, не восстанавливая фото из опубликованных постов.</p>\n<p>И помните: разрез — это инструмент, а не цель. Плитки нужны там, где одно изображение не справляется, а в остальных случаях обычное фото проще и лучше. Используйте разделитель тогда, когда он действительно решает задачу.</p>\n<p>Для школьных и рабочих проектов разделитель помогает оформить плакат из одного большого изображения. Ученики могут напечатать постер на обычном принтере, не обращаясь в типографию, и собрать его на стене класса.</p>\n<p>Если вы разрезаете карту или схему, подпишите каждую плитку номером и стрелкой направления. Карта, разрезанная на части, без подписей превращается в головоломку, а с подписями — в удобный атлас.</p>\n<h2 id=\"quick-reference\">Краткая справка: чек-лист разделения</h2>\n<p>Начните с большого источника, выберите режим «Сетка», «Горизонтальные» или «Вертикальные полосы», задайте строки и столбцы или нажмите предустановку. Проверьте пронумерованные линии разреза в предпросмотре, особенно вокруг лиц и текста.</p>\n<p>Выберите JPG для фото и PNG для прозрачности, скачайте ZIP-архив и публикуйте плитки сетки в обратном порядке. Если разрез лёг неудачно, измените сетку и разделите снова, а не принимайте его.</p>\n<p>Пошаговую версию читайте в статье <a href=\"/ru/blog/kak-razdelit-izobrazhenie/\">Как разделить изображение</a>, а сетку Instagram подробно — в статье <a href=\"/ru/blog/razdelit-foto-dlya-setki-instagram/\">Как разделить фото для сетки Instagram</a>. Разделите изображение в <a href=\"/ru/razdelit-izobrazhenie/\">разделителе изображений</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Чем разделение отличается от обрезки изображения?","answer":"Обрезка сохраняет один кусок изображения и выбрасывает остальное. Разделение сохраняет каждый кусок и даёт вам их все как отдельные файлы. Плитки вместе содержат всё исходное изображение, просто разделённое по прямым линиям разреза."},{"question":"Снизит ли разделение качество моего фото?","answer":"Нет. Плитки разрезаются в полном исходном размере в пикселях, поэтому каждая плитка такая же резкая, как соответствующая часть источника. Качество падает, только если вы начинаете с источника низкого разрешения, потому что плитки тогда тоже маленькие."},{"question":"На какую самую большую сетку можно разделить изображение?","answer":"Максимальная сетка — 10 на 10, что даёт 100 плиток из одного изображения. Большинству задач нужно намного меньше: 3 на 3 для сетки Instagram, 2 на 2 для простого разреза или несколько полос для длинного скриншота."},{"question":"Можно ли разделить изображение на неравные части?","answer":"Нет, разделитель делит изображение на равные плитки или полосы. Если размеры изображения не делятся нацело, крайние плитки могут отличаться на пиксель-другой. Для точных неравных частей обрежьте каждый раздел отдельно с помощью инструмента обрезки."},{"question":"Сохраняют ли разделённые плитки исходный формат файла?","answer":"Формат плиток вы выбираете сами. Источник JPG может дать плитки PNG, а источник PNG — плитки JPG. Выбирайте JPG для фото и маленьких файлов, а PNG, когда нужна прозрачность или точные пиксели."},{"question":"Зачем разделять изображение, а не просто опубликовать всё фото?","answer":"Разделение служит задачам, которые одно изображение не решает: пазл сетки на странице профиля, карусель, которая открывает панораму свайп за свайпом, постер, напечатанный на многих страницах, или длинный скриншот, разделённый на читаемые разделы."}];
